    <title>Computer Languages Quiz</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(18, 24, 42, 0.92);
        --panel-border: rgba(135, 156, 255, 0.16);
        --text: #eef2ff;
        --muted: #aab3d3;
        --accent: #7c9cff;
        --accent-strong: #96adff;
        --success: #7ee0b5;
        --shadow: 0 24px 60px rgba(0, 0, 0, 0.42);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
          sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 28%),
          linear-gradient(180deg, #0a0f1d 0%, #111728 100%);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 32px 16px;
      }

      .app-shell {
        width: min(100%, 860px);
      }

      .quiz-card {
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
        overflow: hidden;
      }

      .quiz-header {
        padding: 32px 32px 12px;
      }

      .eyebrow {
        margin: 0 0 10px;
        color: var(--accent-strong);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0 0 12px;
        font-size: clamp(1.9rem, 4vw, 2.75rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        padding: 20px 32px 32px;
      }

      .form-field {
        margin-bottom: 20px;
        padding: 22px;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 18px;
        background: rgba(255, 255, 255, 0.03);
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-width: 0;
      }

      legend {
        padding: 0;
        margin-bottom: 10px;
        font-size: 1.08rem;
        font-weight: 700;
      }

      .help-text {
        margin: 0 0 16px;
        color: var(--muted);
        font-size: 0.95rem;
        line-height: 1.5;
      }

      .choices {
        display: grid;
        gap: 12px;
      }

      .choice {
        display: flex;
        align-items: center;
        gap: 12px;
        padding: 14px 16px;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 14px;
        background: rgba(255, 255, 255, 0.025);
        transition: border-color 120ms ease, background 120ms ease, transform 120ms ease;
        cursor: pointer;
      }

      .choice:hover {
        border-color: rgba(124, 156, 255, 0.4);
        background: rgba(124, 156, 255, 0.08);
        transform: translateY(-1px);
      }

      .choice input {
        inline-size: 18px;
        block-size: 18px;
        accent-color: var(--accent);
        margin: 0;
        flex: 0 0 auto;
      }

      .choice span {
        line-height: 1.45;
      }

      .actions {
        display: flex;
        align-items: center;
        gap: 16px;
        flex-wrap: wrap;
        margin-top: 28px;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 700;
        color: #09101f;
        background: linear-gradient(135deg, var(--accent-strong), #c1cdff);
        cursor: pointer;
        box-shadow: 0 14px 30px rgba(124, 156, 255, 0.28);
      }

      button:hover {
        filter: brightness(1.04);
      }

      .result {
        color: var(--success);
        font-weight: 600;
        min-height: 1.5em;
      }

      @media (max-width: 640px) {
        .quiz-header,
        form {
          padding-left: 20px;
          padding-right: 20px;
        }

        .form-field {
          padding: 18px;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>
    <script>
      const quizQuestions = [
        {
          id: "question-1",
          prompt: "Which of these are commonly used for web development?",
          helpText: "Select every language that is frequently used to build websites or web apps.",
          answers: ["JavaScript", "Python", "HTML", "C"],
        },
        {
          id: "question-2",
          prompt: "Which of these are statically typed programming languages?",
          answers: ["TypeScript", "Java", "Ruby", "Go"],
        },
        {
          id: "question-3",
          prompt: "Which of these languages are known for systems programming?",
          answers: ["Rust", "C++", "Swift", "C"],
        },
      ];

      function AnswerChoice(questionId, answer, index) {
        const inputId = `${questionId}-choice-${index}`;
        return `
          <label class="choice" for="${inputId}">
            <input type="checkbox" id="${inputId}" name="${questionId}" value="${answer}" />
            <span>${answer}</span>
          </label>
        `;
      }

      function QuizQuestion(question) {
        const describedBy = question.helpText ? `${question.id}-help` : "";
        return `
          <div class="form-field">
            <fieldset ${describedBy ? `aria-describedby="${describedBy}"` : ""}>
              <legend>${question.prompt}</legend>
              ${
                question.helpText
                  ? `<p class="help-text" id="${question.id}-help">${question.helpText}</p>`
                  : ""
              }
              <div class="choices">
                ${question.answers.map((answer, index) => AnswerChoice(question.id, answer, index)).join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

      function App() {
        return `
          <main class="app-shell">
            <section class="quiz-card" aria-labelledby="quiz-title">
              <header class="quiz-header">
                <p class="eyebrow">Interactive quiz</p>
                <h1 id="quiz-title">Computer Languages Quiz</h1>
                <p class="intro">Choose one or more answers for each question, then submit your selections.</p>
              </header>
              <form id="quiz-form">
                ${quizQuestions.map(QuizQuestion).join("")}
                <div class="actions">
                  <button type="submit">Submit Quiz</button>
                  <output id="result" class="result" aria-live="polite"></output>
                </div>
              </form>
            </section>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = App();

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const answeredCount = quizQuestions.filter((question) =>
          document.querySelectorAll(`input[name="${question.id}"]:checked`).length > 0
        ).length;

        const result = document.getElementById("result");
        result.textContent = `Submitted ${answeredCount} of ${quizQuestions.length} questions.`;
      });
    </script>
  </body>
</html>
